<?php
$range=reportRange();$events=reportEvents($range);$in=array_values(array_filter($events,fn($e)=>$e['jenis']==='Inbound'));$out=array_values(array_filter($events,fn($e)=>$e['jenis']==='Outbound'));
heading('','Laporan','Pilih periode untuk melihat aktivitas atau mengunduh laporan.',linkButton('Ekspor CSV',url('laporan',['dari'=>$range[0],'sampai'=>$range[1],'export'=>'csv']),'download'));
?>
<form method="get" class="panel report-filter"><input type="hidden" name="page" value="laporan"><div><strong>Periode aktivitas</strong><p>Kosongkan tanggal untuk menampilkan seluruh riwayat.</p></div><label>Dari tanggal<input type="date" name="dari" value="<?=e($range[0])?>"></label><span class="muted date-separator">—</span><label>Sampai tanggal<input type="date" name="sampai" value="<?=e($range[1])?>"></label><button class="button primary">Tampilkan</button><a class="button secondary" href="<?=e(url('laporan'))?>">Reset</a></form>
<?php stats([['Penempatan inbound',num(count($in)),'Termasuk perpindahan antarrak','in','green'],['Pengiriman outbound',num(count($out)),'Serah terima kepada kurir','out','orange'],['Berat inbound',kg(array_sum(array_column($in,'berat_kg'))),'Akumulasi setiap penempatan','box','blue'],['Berat outbound',kg(array_sum(array_column($out,'berat_kg'))),'Akumulasi paket yang dikirim','truck','purple']]);
$group=[];$cities=[];$couriers=[];$daily=[];
foreach($events as $event){$key=$event['no_resi'];$group[$event['kategori']][$key]=$event;$cities[$event['kota_tujuan']][$key]=$event;$day=substr($event['waktu'],0,10);$daily[$day]??=['Inbound'=>0,'Outbound'=>0,'berat_in'=>0,'berat_out'=>0];$daily[$day][$event['jenis']]++;$daily[$day][$event['jenis']==='Inbound'?'berat_in':'berat_out']+=(float)$event['berat_kg'];if($event['jenis']==='Outbound')$couriers[$event['nama_kurir'].' · '.$event['no_kendaraan']][]=$event;}
function reportGroup(string $title,string $column,array $data):void{echo '<section class="panel"><div class="panel-head"><h2>'.e($title).'</h2></div>';if(!$data){emptyState('Belum ada aktivitas pada periode ini');}else{echo '<div class="table-wrap"><table><thead><tr><th>'.e($column).'</th><th>Paket unik</th><th>Total berat</th><th>Rata-rata</th></tr></thead><tbody>';foreach($data as $label=>$list){$weight=array_sum(array_column($list,'berat_kg'));echo '<tr><td>'.e($label).'</td><td>'.count($list).'</td><td>'.kg($weight).'</td><td>'.kg($weight/count($list)).'</td></tr>';}echo '</tbody></table></div>';}echo '</section>';}
?>
<div class="report-grid"><?php reportGroup('Paket per kategori','Kategori',$group);reportGroup('Paket per tujuan','Kota tujuan',$cities);?></div><p class="report-note">Rekap kategori dan tujuan menghitung satu kali setiap resi yang memiliki aktivitas pada periode terpilih.</p>
<section class="panel section-gap"><div class="panel-head"><h2>Rekap aktivitas harian</h2><span class="muted">Tanggal penempatan & keberangkatan</span></div><?php if(!$daily):emptyState('Tidak ada aktivitas pada periode ini');else:?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Penempatan</th><th>Berat inbound</th><th>Pengiriman</th><th>Berat outbound</th></tr></thead><tbody><?php foreach($daily as $d=>$s):?><tr><td><?=e(date('d M Y',strtotime($d)))?></td><td><?=$s['Inbound']?></td><td><?=kg($s['berat_in'])?></td><td><?=$s['Outbound']?></td><td><?=kg($s['berat_out'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<div class="report-grid section-gap"><?php reportGroup('Pengiriman per kurir','Kurir & kendaraan',$couriers);?><section class="panel"><div class="panel-head"><div><h2>Penggunaan rak saat ini</h2><p>Kondisi terkini, tidak mengikuti filter periode</p></div></div><div class="table-wrap"><table><thead><tr><th>Rak</th><th>Paket aktif</th><th>Terpakai</th><th>Sisa</th></tr></thead><tbody><?php foreach(rackRows() as $r):?><tr><td><?=e($r['kode_rak'])?></td><td><?=$r['jumlah_paket']?></td><td><?=kg($r['kapasitas_terpakai_kg'])?></td><td><?=kg((float)$r['kapasitas_maks_kg']-(float)$r['kapasitas_terpakai_kg'])?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="panel"><div class="panel-head"><div><h2>Rincian aktivitas</h2><p>Data yang disertakan dalam ekspor CSV</p></div><span class="count-pill"><?=count($events)?> aktivitas</span></div><?php if(!$events):emptyState('Tidak ada aktivitas pada periode ini');else:?><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Aktivitas</th><th>Resi</th><th>Tujuan</th><th>Berat</th><th>Petugas</th><th>Status</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td class="muted"><?=e(stamp($event['waktu']))?></td><td><span class="flow-label <?=$event['jenis']==='Inbound'?'green':'orange'?>"><?=icon($event['jenis']==='Inbound'?'in':'out')?><?=e($event['jenis'])?></span></td><td><a class="resi" href="<?=e(url('paket',['resi'=>$event['no_resi']]))?>"><?=e($event['no_resi'])?></a></td><td><?=e($event['kota_tujuan'])?></td><td><?=kg($event['berat_kg'])?></td><td><?=e($event['nama_petugas'])?></td><td><?=badge($event['status'],$event['jenis']==='Outbound')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
